"""Account helpers. Balances are integer cents."""


class InsufficientFunds(ValueError):
    """Raised when a withdrawal or transfer exceeds the source balance."""


class Bank:
    """A bank with its own accounts, isolated from other Bank instances."""

    def __init__(self):
        self._accounts = {}

    def open_account(self, name, initial=0):
        if initial < 0:
            raise ValueError("initial balance must be >= 0, got " + repr(initial))
        if name in self._accounts:
            raise ValueError("account exists: " + name)
        self._accounts[name] = initial

    def deposit(self, name, amount):
        self._check_amount(amount)
        self._accounts[name] += amount

    def withdraw(self, name, amount):
        self._check_amount(amount)
        current = self._accounts[name]
        if current < amount:
            raise InsufficientFunds(
                "account %r has balance %d, cannot withdraw %d" % (name, current, amount))
        self._accounts[name] = current - amount

    def balance(self, name):
        return self._accounts[name]

    def transfer(self, src, dst, amount):
        self._check_amount(amount)
        if src == dst:
            raise ValueError("cannot transfer to the same account: " + repr(src))
        src_balance = self._accounts[src]
        dst_balance = self._accounts[dst]
        if src_balance < amount:
            raise InsufficientFunds(...)
        self._accounts[src] = src_balance - amount
        self._accounts[dst] = dst_balance + amount

    @staticmethod
    def _check_amount(amount):
        if amount <= 0:
            raise ValueError("amount must be > 0, got " + repr(amount))
```

